  1→import { useCallback, useEffect, useMemo, useState } from 'react';
  2→import { type ConnectionTestResult, type PinningMode } from '@cipherbox/sdk-core';
  3→import {
  4→  wrapKey,
  5→  unwrapKey,
  6→  clearBytes,
  7→  deriveByoConfigIpnsKeypair,
  8→  hexToBytes,
  9→  bytesToHex,
 10→} from '@cipherbox/crypto';
 11→import type { ByoIpfsConfig } from '@cipherbox/core';
 12→import { useAuthStore } from '../../stores/auth.store';
 13→import { useQuotaStore } from '../../stores/quota.store';
 14→import { addToIpfs, fetchFromIpfs } from '../../lib/api/ipfs';
 15→import { createAndPublishIpnsRecord, resolveIpnsRecord } from '../../services/ipns.service';
 16→import { ConnectionTest } from './ConnectionTest';
 17→import { MigrationProgress } from './MigrationProgress';
 18→import { migrationApi } from '../../lib/api/migration';
 19→
 20→/** Local storage key for the BYO config IPNS name (not sensitive -- public identifier) */
 21→const BYO_IPNS_NAME_KEY = 'cipherbox-byo-ipns-name';
 22→
 23→type SavedConfig = {
 24→  mode: PinningMode;
 25→  endpoint: string;
 26→  authToken: string;
 27→};
 28→
 29→/**
 30→ * Encrypt ByoIpfsConfig with user's secp256k1 public key (ECIES).
 31→ * Follows the same pattern as @cipherbox/core registry/bin encrypt.
 32→ */
 33→async function encryptByoConfig(
 34→  config: ByoIpfsConfig,
 35→  userPublicKey: Uint8Array
 36→): Promise<Uint8Array> {
 37→  const plaintext = new TextEncoder().encode(JSON.stringify(config));
 38→  try {
 39→    return await wrapKey(plaintext, userPublicKey);
 40→  } finally {
 41→    clearBytes(plaintext);
 42→  }
 43→}
 44→
 45→/**
 46→ * Decrypt ByoIpfsConfig with user's secp256k1 private key (ECIES).
 47→ */
 48→async function decryptByoConfig(
 49→  encrypted: Uint8Array,
 50→  userPrivateKey: Uint8Array
 51→): Promise<ByoIpfsConfig> {
 52→  const plaintext = await unwrapKey(encrypted, userPrivateKey);
 53→  try {
 54→    const json = new TextDecoder().decode(plaintext);
 55→    return JSON.parse(json) as ByoIpfsConfig;
 56→  } finally {
 57→    clearBytes(plaintext);
 58→  }
 59→}
 60→
 61→/**
 62→ * STORAGE tab for the Settings page.
 63→ *
 64→ * Allows users to configure their IPFS pinning mode, external node settings,
 65→ * test connections, and persist BYO config as an encrypted IPNS entry
 66→ * (zero-knowledge -- server never sees credentials).
 67→ */
 68→export function StorageTab() {
 69→  const [mode, setMode] = useState<PinningMode>('cipherbox');
 70→  const [endpoint, setEndpoint] = useState('');
 71→  const [authToken, setAuthToken] = useState('');
 72→  const [savedConfig, setSavedConfig] = useState<SavedConfig | null>(null);
 73→  const [testResult, setTestResult] = useState<ConnectionTestResult | null>(null);
 74→  const [isSaving, setIsSaving] = useState(false);
 75→  const [isLoading, setIsLoading] = useState(true);
 76→  const [saveError, setSaveError] = useState<string | null>(null);
 77→
 78→  const vaultKeypair = useAuthStore((s) => s.vaultKeypair);
 79→  const teeKeys = useAuthStore((s) => s.teeKeys);
 80→  const { usedBytes } = useQuotaStore();
 81→
 82→  // Dirty tracking
 83→  const isDirty = useMemo(() => {
 84→    if (!savedConfig) {
 85→      return mode !== 'cipherbox' || endpoint !== '' || authToken !== '';
 86→    }
 87→    return (
 88→      mode !== savedConfig.mode ||
 89→      endpoint !== savedConfig.endpoint ||
 90→      authToken !== savedConfig.authToken
 91→    );
 92→  }, [mode, endpoint, authToken, savedConfig]);
 93→
 94→  const endpointDirty = savedConfig ? endpoint !== savedConfig.endpoint : endpoint !== '';
 95→  const tokenDirty = savedConfig ? authToken !== savedConfig.authToken : authToken !== '';
 96→
 97→  // Load saved config from encrypted IPNS entry on mount
 98→  useEffect(() => {
 99→    let cancelled = false;
100→
101→    async function loadConfig() {
102→      if (!vaultKeypair?.privateKey) {
103→        setIsLoading(false);
104→        return;
105→      }
106→
107→      try {
108→        const keypair = await deriveByoConfigIpnsKeypair(vaultKeypair.privateKey);
109→        const storedIpnsName = localStorage.getItem(BYO_IPNS_NAME_KEY);
110→
111→        // Use stored name or derived name
112→        const ipnsName = storedIpnsName || keypair.ipnsName;
113→
114→        // Try resolving the BYO config IPNS record
115→        const resolved = await resolveIpnsRecord(ipnsName);
116→        if (cancelled) return;
117→
118→        if (resolved?.cid) {
119→          const encrypted = await fetchFromIpfs(resolved.cid);
120→          if (cancelled) return;
121→
122→          const config = await decryptByoConfig(encrypted, vaultKeypair.privateKey);
123→          if (cancelled) return;
124→
125→          setMode(config.pinningMode);
126→          setEndpoint(config.externalProvider?.endpoint ?? '');
127→          setAuthToken(config.externalProvider?.authToken ?? '');
128→          setSavedConfig({
129→            mode: config.pinningMode,
130→            endpoint: config.externalProvider?.endpoint ?? '',
131→            authToken: config.externalProvider?.authToken ?? '',
132→          });
133→
134→          // Cache the IPNS name
135→          localStorage.setItem(BYO_IPNS_NAME_KEY, ipnsName);
136→        }
137→      } catch {
138→        // No saved config or decryption failed -- use defaults
139→      } finally {
140→        if (!cancelled) {
141→          setIsLoading(false);
142→        }
143→      }
144→    }
145→
146→    loadConfig();
147→    return () => {
148→      cancelled = true;
149→    };
150→  }, [vaultKeypair]);
151→
152→  const handleSave = useCallback(async () => {
153→    if (!vaultKeypair?.privateKey || !vaultKeypair?.publicKey || isSaving) return;
154→    setIsSaving(true);
155→    setSaveError(null);
156→
157→    try {
158→      // 1. Construct ByoIpfsConfig
159→      const config: ByoIpfsConfig = {
160→        pinningMode: mode,
161→        externalProvider:
162→          mode !== 'cipherbox'
163→            ? {
164→                endpoint,
165→                authToken,
166→                protocol: testResult?.protocol ?? 'kubo',
167→                providerName: testResult?.version,
168→              }
169→            : null,
170→      };
171→
172→      // 2. Encrypt with user's public key (ECIES)
173→      const encrypted = await encryptByoConfig(config, vaultKeypair.publicKey);
174→
175→      // 3. Upload encrypted blob to IPFS (pass typed array directly per CLAUDE.md)
176→      const blob = new Blob([encrypted as BlobPart]);
177→      const { cid } = await addToIpfs(blob);
178→
179→      // 4. Derive dedicated IPNS keypair for BYO config
180→      const byoKeypair = await deriveByoConfigIpnsKeypair(vaultKeypair.privateKey);
181→
182→      // 5. Get current sequence number (try resolving existing)
183→      let sequenceNumber = BigInt(0);
184→      const storedIpnsName = localStorage.getItem(BYO_IPNS_NAME_KEY);
185→      if (storedIpnsName) {
186→        try {
187→          const existing = await resolveIpnsRecord(storedIpnsName);
188→          if (existing?.sequenceNumber) {
189→            sequenceNumber = BigInt(existing.sequenceNumber);
190→          }
191→        } catch {
192→          // First publish -- sequence 0
193→        }
194→      }
195→
196→      // 6. Wrap IPNS private key with TEE public key for republishing
197→      let encryptedIpnsPrivateKey: string | undefined;
198→      let keyEpoch: number | undefined;
199→      if (teeKeys?.currentPublicKey) {
200→        const teePublicKey = hexToBytes(teeKeys.currentPublicKey);
201→        const wrappedKey = await wrapKey(byoKeypair.privateKey, teePublicKey);
202→        encryptedIpnsPrivateKey = bytesToHex(wrappedKey);
203→        keyEpoch = teeKeys.currentEpoch;
204→      }
205→
206→      // 7. Publish encrypted blob via IPNS
207→      await createAndPublishIpnsRecord({
208→        ipnsPrivateKey: byoKeypair.privateKey,
209→        ipnsName: byoKeypair.ipnsName,
210→        metadataCid: cid,
211→        sequenceNumber,
212→        encryptedIpnsPrivateKey,
213→        keyEpoch,
214→      });
215→
216→      // 8. Store IPNS name in localStorage (public identifier, not sensitive)
217→      localStorage.setItem(BYO_IPNS_NAME_KEY, byoKeypair.ipnsName);
218→
219→      // 9. Update saved config state
220→      setSavedConfig({
221→        mode,
222→        endpoint,
223→        authToken,
224→      });
225→
226→      // 10. Trigger migration if provider changed and user has existing pins
227→      const providerChanged =
228→        savedConfig &&
229→        (savedConfig.mode !== mode || savedConfig.endpoint !== endpoint) &&
230→        usedBytes > 0;
231→
232→      if (providerChanged && teeKeys?.currentPublicKey) {
233→        // ECIES-wrap source and destination provider configs for TEE
234→        const teePublicKey = hexToBytes(teeKeys.currentPublicKey);
235→
236→        const sourceConfig = JSON.stringify(
237→          savedConfig.mode !== 'cipherbox'
238→            ? {
239→                endpoint: savedConfig.endpoint,
240→                authToken: savedConfig.authToken,
241→                protocol: 'kubo',
242→              }
243→            : { endpoint: 'cipherbox', protocol: 'cipherbox' }
244→        );
245→        const destConfig = JSON.stringify({
246→          endpoint,
247→          authToken,
248→          protocol: testResult?.protocol ?? 'kubo',
249→        });
250→
251→        const sourceConfigEncrypted = bytesToHex(
252→          await wrapKey(new TextEncoder().encode(sourceConfig), teePublicKey)
253→        );
254→        const destConfigEncrypted = bytesToHex(
255→          await wrapKey(new TextEncoder().encode(destConfig), teePublicKey)
256→        );
257→
258→        await migrationApi.start(sourceConfigEncrypted, destConfigEncrypted);
259→      }
260→
261→      // 11. Refetch quota to update advisory status
262→      useQuotaStore.getState().fetchQuota();
263→    } catch (err) {
264→      setSaveError(
265→        err instanceof Error ? err.message : 'failed to save storage settings. try again.'
266→      );
267→    } finally {
268→      setIsSaving(false);
269→    }
270→  }, [
271→    vaultKeypair,
272→    mode,
273→    endpoint,
274→    authToken,
275→    testResult,
276→    teeKeys,
277→    savedConfig,
278→    usedBytes,
279→    isSaving,
280→  ]);
281→
282→  const handleDiscard = useCallback(() => {
283→    if (savedConfig) {
