285→      setEndpoint(savedConfig.endpoint);
286→      setAuthToken(savedConfig.authToken);
287→    } else {
288→      setMode('cipherbox');
289→      setEndpoint('');
290→      setAuthToken('');
291→    }
292→    setTestResult(null);
293→    setSaveError(null);
294→  }, [savedConfig]);
295→
296→  if (isLoading) {
297→    return (
298→      <div className="settings-storage">
299→        <p className="settings-section-description">loading storage settings...</p>
