 1→/**
 2→ * CipherBox TEE Worker
 3→ *
 4→ * Standalone Express HTTP server for Phala Cloud CVM deployment.
 5→ * Receives encrypted IPNS private keys, decrypts with epoch-derived keys,
 6→ * signs IPNS records, and returns signed records.
 7→ *
 8→ * Routes:
 9→ *   GET  /health      - Public health check
10→ *   GET  /public-key  - TEE public key per epoch (auth required)
11→ *   POST /republish   - Batch IPNS signing (auth required)
12→ *   POST /migrate     - Batch CID migration between providers (auth required)
13→ */
14→
15→import express from 'express';
16→import { authMiddleware } from './middleware/auth.js';
17→import healthRouter from './routes/health.js';
18→import publicKeyRouter from './routes/public-key.js';
19→import republishRouter from './routes/republish.js';
20→import migrateRouter from './routes/migrate.js';
21→
22→const app = express();
23→const port = parseInt(process.env.PORT || '3001', 10);
24→const mode = process.env.TEE_MODE || 'simulator';
25→
26→// JSON body parsing with 10mb limit for batch requests
27→app.use(express.json({ limit: '10mb' }));
28→
29→// Public routes (no auth)
30→app.use(healthRouter);
31→
32→// Protected routes (auth required)
33→app.use(authMiddleware, publicKeyRouter);
34→app.use(authMiddleware, republishRouter);
35→app.use(authMiddleware, migrateRouter);
36→
37→app.listen(port, () => {
38→  console.log(`TEE Worker started on port ${port} (mode: ${mode})`);
39→});
40→
41→export default app;
