  3→import { TeeKeyStateService } from './tee-key-state.service';
  4→
  5→/**
  6→ * A single entry in a batch republish request to the TEE worker.
  7→ */
  8→export interface RepublishEntry {
  9→  /** Base64-encoded ECIES-encrypted IPNS Ed25519 private key */
 10→  encryptedIpnsKey: string;
 11→  /** TEE key epoch the IPNS key was encrypted for */
 12→  keyEpoch: number;
 13→  /** IPNS name (k51... or bafzaa...) */
 14→  ipnsName: string;
 15→  /** CID of the latest encrypted folder metadata */
 16→  latestCid: string;
 17→  /** Current IPNS sequence number (bigint as string) */
 18→  sequenceNumber: string;
 19→  /** Current active TEE epoch */
 20→  currentEpoch: number;
 21→  /** Previous TEE epoch (null if no grace period active) */
 22→  previousEpoch: number | null;
 23→}
 24→
 25→/**
 26→ * Result for a single entry in a batch republish response from the TEE worker.
 27→ */
 28→export interface RepublishResult {
 29→  /** IPNS name this result corresponds to */
 30→  ipnsName: string;
 31→  /** Whether the signing succeeded */
 32→  success: boolean;
 33→  /** Base64-encoded signed IPNS record (present on success) */
 34→  signedRecord?: string;
 35→  /** New sequence number after signing (present on success) */
 36→  newSequenceNumber?: string;
 37→  /** Base64-encoded re-encrypted IPNS key if epoch was upgraded (present if key epoch changed) */
 38→  upgradedEncryptedKey?: string;
 39→  /** New key epoch if the key was re-encrypted (present if key epoch changed) */
 40→  upgradedKeyEpoch?: number;
 41→  /** Error message (present on failure) */
 42→  error?: string;
 43→}
 44→
 45→/** Default timeout for TEE worker HTTP requests (30 seconds) */
 46→const TEE_REQUEST_TIMEOUT_MS = 30_000;
 47→
 48→@Injectable()
 49→export class TeeService {
 50→  private readonly logger = new Logger(TeeService.name);
 51→  private readonly teeWorkerUrl: string;
 52→  private readonly teeWorkerSecret: string;
 53→
 54→  constructor(
 55→    private readonly configService: ConfigService,
 56→    private readonly teeKeyStateService: TeeKeyStateService
 57→  ) {
 58→    this.teeWorkerUrl = this.configService.get<string>('TEE_WORKER_URL', 'http://localhost:3001');
 59→    this.teeWorkerSecret = this.configService.get<string>('TEE_WORKER_SECRET', '');
 60→  }
 61→
 62→  /**
 63→   * Check TEE worker health and get current epoch.
 64→   */
 65→  async getHealth(): Promise<{ healthy: boolean; epoch: number }> {
 66→    const response = await this.fetchWithTimeout(`${this.teeWorkerUrl}/health`, {
 67→      method: 'GET',
 68→      headers: this.authHeaders(),
 69→    });
 70→
 71→    if (!response.ok) {
 72→      throw new Error(`TEE worker health check failed: HTTP ${response.status}`);
 73→    }
 74→
 75→    const data = (await response.json()) as { healthy: boolean; epoch: number };
 76→    return data;
 77→  }
 78→
 79→  /**
 80→   * Get the TEE worker's public key for a specific epoch.
 81→   * Returns the 65-byte uncompressed secp256k1 public key.
 82→   */
 83→  async getPublicKey(epoch: number): Promise<Uint8Array> {
 84→    const response = await this.fetchWithTimeout(`${this.teeWorkerUrl}/public-key?epoch=${epoch}`, {
 85→      method: 'GET',
 86→      headers: this.authHeaders(),
 87→    });
 88→
 89→    if (!response.ok) {
 90→      throw new Error(`TEE worker public key request failed: HTTP ${response.status}`);
 91→    }
 92→
 93→    const data = (await response.json()) as { publicKey: string };
 94→    const publicKeyBytes = new Uint8Array(Buffer.from(data.publicKey, 'hex'));
 95→
 96→    if (publicKeyBytes.length !== 65 || publicKeyBytes[0] !== 0x04) {
 97→      throw new Error(
 98→        `Invalid TEE public key: expected 65 bytes with 0x04 prefix, got ${publicKeyBytes.length} bytes`
 99→      );
100→    }
101→
102→    return publicKeyBytes;
103→  }
104→
105→  /**
106→   * Send a batch of entries to the TEE worker for IPNS record signing.
107→   * The TEE worker decrypts IPNS keys, signs new records, and returns results.
108→   */
109→  async republish(entries: RepublishEntry[]): Promise<RepublishResult[]> {
110→    this.logger.log(`Sending ${entries.length} entries to TEE worker for republishing`);
111→
112→    const response = await this.fetchWithTimeout(`${this.teeWorkerUrl}/republish`, {
113→      method: 'POST',
114→      headers: {
115→        ...this.authHeaders(),
116→        'Content-Type': 'application/json',
117→      },
118→      body: JSON.stringify({ entries }),
119→    });
120→
121→    if (!response.ok) {
122→      throw new Error(`TEE worker republish failed: HTTP ${response.status}`);
123→    }
124→
125→    const data = (await response.json()) as { results: RepublishResult[] };
126→    const successCount = data.results.filter((r) => r.success).length;
127→    this.logger.log(
128→      `TEE republish complete: ${successCount}/${data.results.length} entries succeeded`
129→    );
130→
131→    return data.results;
132→  }
133→
134→  /**
135→   * Initialize TEE key state from the TEE worker on module startup.
136→   * If tee_key_state is empty, queries TEE for epoch 1 public key and initializes.
137→   * If tee_key_state has data, validates it still matches the TEE worker.
138→   * Gracefully handles TEE worker being unavailable (logs warning, does not throw).
139→   */
140→  async initializeFromTee(): Promise<void> {
141→    try {
142→      // Check TEE worker health first
143→      const health = await this.getHealth();
144→      this.logger.log(`TEE worker healthy, current epoch: ${health.epoch}`);
145→
146→      const currentState = await this.teeKeyStateService.getCurrentState();
147→
148→      if (!currentState) {
149→        // First boot: initialize from TEE worker
150→        const publicKey = await this.getPublicKey(health.epoch);
151→        await this.teeKeyStateService.initializeEpoch(health.epoch, publicKey);
152→        this.logger.log(`TEE key state initialized from worker at epoch ${health.epoch}`);
153→        return;
154→      }
155→
156→      // Validate existing state matches TEE worker
157→      if (currentState.currentEpoch !== health.epoch) {
158→        this.logger.warn(
159→          `TEE epoch mismatch: DB has epoch ${currentState.currentEpoch}, TEE worker reports epoch ${health.epoch}. ` +
160→            'This may indicate a TEE worker update. Manual epoch rotation may be needed.'
161→        );
162→      } else {
163→        this.logger.log(
164→          `TEE key state validated: epoch ${currentState.currentEpoch} matches worker`
165→        );
166→      }
167→    } catch (error) {
168→      // TEE worker unavailable - this is expected during development
169→      // and acceptable for startup (republishing will retry later)
170→      const message = error instanceof Error ? error.message : String(error);
171→      this.logger.warn(`TEE worker unavailable during initialization: ${message}`);
172→      this.logger.warn(
173→        'TEE republishing will not work until the TEE worker is available. ' +
174→          'This is expected in development without a TEE simulator.'
175→      );
176→    }
177→  }
178→
179→  /**
180→   * Build authorization headers for TEE worker requests.
181→   * IMPORTANT: Never log the secret value.
182→   */
183→  private authHeaders(): Record<string, string> {
184→    const headers: Record<string, string> = {};
185→    if (this.teeWorkerSecret) {
186→      headers['Authorization'] = `Bearer ${this.teeWorkerSecret}`;
187→    }
188→    return headers;
189→  }
190→
191→  /**
192→   * Fetch with a timeout to prevent hanging requests.
193→   */
194→  private async fetchWithTimeout(url: string, init: RequestInit): Promise<Response> {
195→    const controller = new AbortController();
196→    const timeout = setTimeout(() => controller.abort(), TEE_REQUEST_TIMEOUT_MS);
197→
198→    try {
199→      return await fetch(url, {
200→        ...init,
201→        signal: controller.signal,
202→      });
203→    } catch (error) {
204→      if (error instanceof Error && error.name === 'AbortError') {
205→        throw new Error(`TEE worker request timed out after ${TEE_REQUEST_TIMEOUT_MS}ms: ${url}`);
206→      }
207→      throw error;
208→    } finally {
209→      clearTimeout(timeout);
210→    }
211→  }
212→}
213→

 1→import { Module, Logger, OnModuleInit } from '@nestjs/common';
 2→import { TypeOrmModule } from '@nestjs/typeorm';
 3→import { ConfigModule } from '@nestjs/config';
 4→import { TeeKeyState } from './tee-key-state.entity';
 5→import { TeeKeyRotationLog } from './tee-key-rotation-log.entity';
 6→import { TeeKeyStateService } from './tee-key-state.service';
 7→import { TeeService } from './tee.service';
 8→
 9→@Module({
10→  imports: [TypeOrmModule.forFeature([TeeKeyState, TeeKeyRotationLog]), ConfigModule],
11→  providers: [TeeService, TeeKeyStateService],
12→  exports: [TeeService, TeeKeyStateService],
13→})
14→export class TeeModule implements OnModuleInit {
15→  private readonly logger = new Logger(TeeModule.name);
16→
17→  constructor(private readonly teeService: TeeService) {}
18→
19→  async onModuleInit(): Promise<void> {
20→    try {
21→      await this.teeService.initializeFromTee();
22→    } catch (error) {
23→      // Never crash the application if TEE is unavailable
24→      const message = error instanceof Error ? error.message : String(error);
25→      this.logger.warn(`TEE initialization failed (non-fatal): ${message}`);
26→    }
27→  }
28→}
