  1→/**
  2→ * Republish Route
  3→ *
  4→ * POST /republish - Batch IPNS record signing endpoint.
  5→ *
  6→ * Receives encrypted IPNS private keys, decrypts with epoch-derived keys,
  7→ * signs IPNS records, and returns signed records. Each entry is processed
  8→ * independently -- one failure does not block others.
  9→ *
 10→ * SECURITY:
 11→ * - IPNS private keys are zeroed immediately after signing
 12→ * - No key material appears in logs or error messages
 13→ * - Per-entry error handling with safe error messages
 14→ */
 15→
 16→import { Router, type Request, type Response } from 'express';
 17→import { decryptWithFallback, reEncryptForEpoch } from '../services/key-manager.js';
 18→import { signIpnsRecord } from '../services/ipns-signer.js';
 19→
 20→const router = Router();
 21→
 22→/** Shape of each entry in the republish request */
 23→interface RepublishEntry {
 24→  encryptedIpnsKey: string; // base64-encoded ECIES ciphertext
 25→  keyEpoch: number;
 26→  ipnsName: string;
 27→  latestCid: string;
 28→  sequenceNumber: string; // bigint as string
 29→  currentEpoch: number;
 30→  previousEpoch: number | null;
 31→}
 32→
 33→/** Shape of each result in the republish response */
 34→interface RepublishResult {
 35→  ipnsName: string;
 36→  success: boolean;
 37→  signedRecord?: string; // base64-encoded marshaled IPNS record
 38→  newSequenceNumber?: string;
 39→  upgradedEncryptedKey?: string; // base64, present if re-encrypted for current epoch
 40→  upgradedKeyEpoch?: number;
 41→  error?: string;
 42→}
 43→
 44→router.post('/republish', async (req: Request, res: Response) => {
 45→  const { entries } = req.body as { entries: RepublishEntry[] };
 46→
 47→  if (!entries || !Array.isArray(entries)) {
 48→    res.status(400).json({ error: 'Missing or invalid entries array' });
 49→    return;
 50→  }
 51→
 52→  const results: RepublishResult[] = [];
 53→  let successes = 0;
 54→  let failures = 0;
 55→
 56→  for (const entry of entries) {
 57→    let ipnsPrivateKey: Uint8Array | null = null;
 58→
 59→    try {
 60→      // 1. Decode encrypted IPNS key from base64
 61→      const encryptedIpnsKey = new Uint8Array(Buffer.from(entry.encryptedIpnsKey, 'base64'));
 62→
 63→      // 2. Decrypt with epoch fallback
 64→      const { ipnsPrivateKey: decryptedKey, usedEpoch } = await decryptWithFallback(
 65→        encryptedIpnsKey,
 66→        entry.currentEpoch,
 67→        entry.previousEpoch
 68→      );
 69→      ipnsPrivateKey = decryptedKey;
 70→
 71→      // 3. Sign IPNS record with incremented sequence number
 72→      const newSequenceNumber = BigInt(entry.sequenceNumber) + 1n;
 73→      const signedRecord = await signIpnsRecord(ipnsPrivateKey, entry.latestCid, newSequenceNumber);
 74→
 75→      // 4. Check if re-encryption needed (used previous epoch, not current)
 76→      let upgradedEncryptedKey: string | undefined;
 77→      let upgradedKeyEpoch: number | undefined;
 78→
 79→      if (usedEpoch !== entry.currentEpoch) {
 80→        const reEncrypted = await reEncryptForEpoch(ipnsPrivateKey, entry.currentEpoch);
 81→        upgradedEncryptedKey = Buffer.from(reEncrypted).toString('base64');
 82→        upgradedKeyEpoch = entry.currentEpoch;
 83→      }
 84→
 85→      // 5. IMMEDIATELY zero the IPNS private key
 86→      ipnsPrivateKey.fill(0);
 87→      ipnsPrivateKey = null;
 88→
 89→      // 6. Build success result
 90→      const result: RepublishResult = {
 91→        ipnsName: entry.ipnsName,
 92→        success: true,
 93→        signedRecord: Buffer.from(signedRecord).toString('base64'),
 94→        newSequenceNumber: newSequenceNumber.toString(),
 95→      };
 96→
 97→      if (upgradedEncryptedKey) {
 98→        result.upgradedEncryptedKey = upgradedEncryptedKey;
 99→        result.upgradedKeyEpoch = upgradedKeyEpoch;
100→      }
101→
102→      results.push(result);
103→      successes++;
104→    } catch (error) {
105→      // Ensure key is zeroed even on error
106→      if (ipnsPrivateKey) {
107→        ipnsPrivateKey.fill(0);
108→        ipnsPrivateKey = null;
109→      }
110→
111→      // Never include key material in error messages
112→      results.push({
113→        ipnsName: entry.ipnsName,
114→        success: false,
115→        error: error instanceof Error ? error.message : 'Unknown error',
116→      });
117→      failures++;
118→    }
119→  }
120→
121→  // Log processing summary (NEVER log key material)
122→  console.log(
123→    `Republish batch: ${entries.length} entries, ${successes} successes, ${failures} failures`
124→  );
125→
126→  res.json({ results });
127→});
128→
129→export default router;
130→

 1→/**
 2→ * TEE Key Derivation Service
 3→ *
 4→ * Derives deterministic secp256k1 keypairs per epoch.
 5→ * - Simulator mode: HKDF-SHA256 from a fixed seed (development/testing)
 6→ * - CVM mode: DstackClient.getKey() for hardware-backed derivation (production)
 7→ */
 8→
 9→import { hkdf } from '@noble/hashes/hkdf';
10→import { sha256 } from '@noble/hashes/sha256';
11→import * as secp from '@noble/secp256k1';
12→
13→/** Cache public keys per epoch to avoid repeated derivation */
14→const publicKeyCache = new Map<number, Uint8Array>();
15→
16→/**
17→ * Derive a deterministic secp256k1 keypair for a given epoch.
18→ *
19→ * In simulator mode, uses HKDF-SHA256 with a fixed seed.
20→ * In CVM mode, uses Phala dstack SDK for hardware-backed derivation.
21→ *
22→ * @param epoch - The key epoch number
23→ * @returns Object with publicKey (65 bytes, uncompressed) and privateKey (32 bytes)
24→ */
25→export async function getKeypair(
26→  epoch: number
27→): Promise<{ publicKey: Uint8Array; privateKey: Uint8Array }> {
28→  const mode = process.env.TEE_MODE || 'simulator';
29→
30→  const env = process.env.CIPHERBOX_ENVIRONMENT;
31→  if (
32→    mode === 'simulator' &&
33→    (env === 'production' || (!env && process.env.NODE_ENV === 'production'))
34→  ) {
35→    throw new Error(
36→      'TEE_MODE=simulator is not allowed in production. Set TEE_MODE=cvm for production deployments, or set CIPHERBOX_ENVIRONMENT explicitly.'
37→    );
38→  }
39→
40→  let privateKey: Uint8Array;
41→
42→  if (mode === 'cvm') {
43→    // Production: Phala Cloud CVM with dstack SDK
44→    // Dynamic import -- @phala/dstack-sdk is only available inside CVM
45→    const { DstackClient } = await import('@phala/dstack-sdk');
46→    const client = new DstackClient();
47→    const keyResult = await client.getKey('cipherbox/ipns-republish', `epoch-${epoch}`);
48→    privateKey = keyResult.asUint8Array().slice(0, 32);
49→  } else {
50→    // Simulator: deterministic HKDF derivation from fixed seed
51→    const seed = new TextEncoder().encode('cipherbox-tee-simulator-seed');
52→    const salt = new TextEncoder().encode('cipherbox-dev');
53→    const info = new TextEncoder().encode(`epoch-${epoch}`);
54→    privateKey = hkdf(sha256, seed, salt, info, 32);
55→  }
56→
57→  // Derive uncompressed public key (65 bytes, 0x04 prefix)
58→  const publicKey = secp.getPublicKey(privateKey, false);
59→
60→  // Cache public key for this epoch
61→  publicKeyCache.set(epoch, publicKey);
62→
63→  return { publicKey, privateKey };
64→}
65→
66→/**
67→ * Get the cached public key for an epoch, or derive it.
68→ *
69→ * @param epoch - The key epoch number
70→ * @returns 65-byte uncompressed secp256k1 public key
71→ */
72→export async function getPublicKey(epoch: number): Promise<Uint8Array> {
73→  const cached = publicKeyCache.get(epoch);
74→  if (cached) {
75→    return cached;
76→  }
77→
78→  const { publicKey } = await getKeypair(epoch);
79→  return publicKey;
80→}
81→

 1→/**
 2→ * Shared Secret Authentication Middleware
 3→ *
 4→ * Validates requests against the TEE_WORKER_SECRET environment variable.
 5→ * Uses Bearer token authentication in the Authorization header.
 6→ */
 7→
 8→import { timingSafeEqual as cryptoTimingSafeEqual } from 'node:crypto';
 9→import type { Request, Response, NextFunction } from 'express';
10→
11→/**
12→ * Express middleware that validates the Authorization: Bearer <secret> header.
13→ *
14→ * Compares the provided token against TEE_WORKER_SECRET env var.
15→ * Returns 401 if missing or mismatched.
16→ */
17→export function authMiddleware(req: Request, res: Response, next: NextFunction): void {
18→  const expectedSecret = process.env.TEE_WORKER_SECRET;
19→
20→  if (!expectedSecret) {
21→    res.status(500).json({ error: 'TEE_WORKER_SECRET not configured' });
22→    return;
23→  }
24→
25→  const authHeader = req.headers.authorization;
26→  if (!authHeader || !authHeader.startsWith('Bearer ')) {
27→    res.status(401).json({ error: 'Missing or invalid Authorization header' });
28→    return;
29→  }
30→
31→  const token = authHeader.slice(7); // Remove 'Bearer ' prefix
32→
33→  // Constant-time comparison to prevent timing attacks
34→  if (
35→    token.length !== expectedSecret.length ||
36→    !cryptoTimingSafeEqual(Buffer.from(token), Buffer.from(expectedSecret))
37→  ) {
38→    res.status(401).json({ error: 'Invalid authentication token' });
39→    return;
40→  }
41→
42→  next();
43→}
44→

 1→/**
 2→ * Key Manager Service
 3→ *
 4→ * ECIES decryption of IPNS private keys with epoch fallback and re-encryption.
 5→ * - Decrypts IPNS keys encrypted with TEE epoch public key
 6→ * - Supports fallback to previous epoch during grace period
 7→ * - Re-encrypts old-epoch keys with current epoch key
 8→ *
 9→ * SECURITY: Caller is responsible for zeroing returned IPNS private keys after use.
10→ */
11→
12→import { decrypt, encrypt } from 'eciesjs';
13→import { getKeypair, getPublicKey } from './tee-keys.js';
14→
15→/**
16→ * Decrypt an ECIES-encrypted IPNS private key using the specified epoch's private key.
17→ *
18→ * @param encryptedIpnsKey - ECIES ciphertext containing the IPNS Ed25519 private key
19→ * @param epoch - The key epoch to use for decryption
20→ * @returns 32-byte Ed25519 IPNS private key
21→ * @throws Error if decryption fails (wrong epoch or corrupted data)
22→ */
23→export async function decryptIpnsKey(
24→  encryptedIpnsKey: Uint8Array,
25→  epoch: number
26→): Promise<Uint8Array> {
27→  const keypair = await getKeypair(epoch);
28→  try {
29→    return new Uint8Array(decrypt(keypair.privateKey, encryptedIpnsKey));
30→  } finally {
31→    keypair.privateKey.fill(0);
32→  }
33→}
34→
35→/**
36→ * Decrypt an IPNS key with fallback from current to previous epoch.
37→ *
38→ * Tries the current epoch first. If decryption fails and a previous epoch
39→ * is provided, tries the previous epoch (grace period support).
40→ *
41→ * @param encryptedIpnsKey - ECIES ciphertext
42→ * @param currentEpoch - Current active epoch number
43→ * @param previousEpoch - Previous epoch number (null if no grace period active)
44→ * @returns Object with decrypted key and which epoch succeeded
45→ * @throws Error if both epochs fail
46→ */
47→export async function decryptWithFallback(
48→  encryptedIpnsKey: Uint8Array,
49→  currentEpoch: number,
50→  previousEpoch: number | null
51→): Promise<{ ipnsPrivateKey: Uint8Array; usedEpoch: number }> {
52→  // Try current epoch first
53→  try {
54→    const ipnsPrivateKey = await decryptIpnsKey(encryptedIpnsKey, currentEpoch);
55→    return { ipnsPrivateKey, usedEpoch: currentEpoch };
56→  } catch {
57→    // Current epoch failed -- try previous if available
58→  }
59→
60→  // Try previous epoch (grace period)
61→  if (previousEpoch !== null) {
62→    try {
63→      const ipnsPrivateKey = await decryptIpnsKey(encryptedIpnsKey, previousEpoch);
64→      return { ipnsPrivateKey, usedEpoch: previousEpoch };
65→    } catch {
66→      // Previous epoch also failed
67→    }
68→  }
69→
70→  throw new Error('ECIES decryption failed for all available epochs');
71→}
72→
73→/**
74→ * Re-encrypt an IPNS private key for a target epoch.
75→ *
76→ * Used during epoch migration: when a key was decrypted with the previous epoch,
77→ * it gets re-encrypted with the current epoch's public key so future republishes
78→ * use the current epoch directly.
79→ *
80→ * @param ipnsPrivateKey - Plaintext 32-byte Ed25519 IPNS private key
81→ * @param targetEpoch - The epoch to encrypt for
82→ * @returns ECIES ciphertext encrypted with target epoch's public key
83→ */
84→export async function reEncryptForEpoch(
85→  ipnsPrivateKey: Uint8Array,
86→  targetEpoch: number
87→): Promise<Uint8Array> {
88→  const targetPublicKey = await getPublicKey(targetEpoch);
89→  const reEncrypted = new Uint8Array(encrypt(targetPublicKey, ipnsPrivateKey));
90→  return reEncrypted;
91→}
92→

 1→/**
 2→ * Public Key Route
 3→ *
 4→ * GET /public-key?epoch=N - Returns the TEE public key for a given epoch.
 5→ * Protected by auth middleware.
 6→ */
 7→
 8→import { Router, type Request, type Response } from 'express';
 9→import { getKeypair } from '../services/tee-keys.js';
10→
11→const router = Router();
12→
13→router.get('/public-key', async (req: Request, res: Response) => {
14→  const epochStr = req.query.epoch as string | undefined;
15→
16→  if (!epochStr || isNaN(Number(epochStr))) {
17→    res.status(400).json({ error: 'Missing or invalid epoch query parameter' });
18→    return;
19→  }
20→
21→  const epoch = parseInt(epochStr, 10);
22→
23→  try {
24→    const { publicKey } = await getKeypair(epoch);
25→
26→    // Return hex-encoded uncompressed public key (65 bytes = 130 hex chars)
27→    const publicKeyHex = Buffer.from(publicKey).toString('hex');
28→
29→    res.json({
30→      epoch,
31→      publicKey: publicKeyHex,
32→    });
33→  } catch (error) {
34→    console.error(`Failed to derive key for epoch ${epoch}:`, (error as Error).message);
35→    res.status(500).json({ error: 'Key derivation failed' });
36→  }
37→});
38→
39→export default router;
40→

 1→/**
 2→ * Migration Route
 3→ *
 4→ * POST /migrate - Batch CID migration endpoint.
 5→ *
 6→ * Receives ECIES-encrypted provider configs and a list of CIDs to migrate.
 7→ * Decrypts configs in-enclave, fetches encrypted blobs from source provider,
 8→ * pins to destination provider, and verifies CID integrity.
 9→ *
10→ * SECURITY:
11→ * - Provider credentials decrypted only inside TEE
12→ * - Auth tokens zeroed after migration batch completes
13→ * - SSRF protection on user-provided endpoint URLs
14→ * - No plaintext content access (opaque encrypted ciphertext)
15→ */
16→
17→import { Router, type Request, type Response } from 'express';
18→import { migrateBatch } from '../services/migration-worker.js';
19→
20→const router = Router();
21→
22→/** Current TEE epoch -- in production this would come from tee-keys state */
23→const TEE_EPOCH = parseInt(process.env.TEE_CURRENT_EPOCH || '1', 10);
24→
25→router.post('/migrate', async (req: Request, res: Response) => {
26→  const { cids, sourceConfigEncrypted, destConfigEncrypted } = req.body as {
27→    cids?: string[];
28→    sourceConfigEncrypted?: string;
29→    destConfigEncrypted?: string;
30→  };
31→
32→  if (!cids || !Array.isArray(cids) || !sourceConfigEncrypted || !destConfigEncrypted) {
33→    res.status(400).json({
34→      error: 'Missing required fields: cids, sourceConfigEncrypted, destConfigEncrypted',
35→    });
36→    return;
37→  }
38→
39→  try {
40→    const result = await migrateBatch(cids, sourceConfigEncrypted, destConfigEncrypted, TEE_EPOCH);
41→
42→    // Log migration summary (NEVER log credentials or config contents)
43→    console.log(
44→      `Migration batch: ${cids.length} CIDs, ${result.succeeded.length} succeeded, ${result.failed.length} failed`
45→    );
46→
47→    res.status(200).json(result);
48→  } catch (err) {
49→    console.error('Migration batch failed:', err instanceof Error ? err.message : 'Unknown error');
50→    res.status(500).json({
51→      error: err instanceof Error ? err.message : 'Migration failed',
52→    });
53→  }
54→});
55→
56→export default router;
57→

