async () => {
  const files = [];
  for (let i = 1; i <= 5; i++) {
    const blob = new Blob([crypto.getRandomValues(new Uint8Array(1024 * 1024 * 10))], { type: 'application/octet-stream' });
    files.push(new File([blob], `large-test-${i}.bin`, { type: 'application/octet-stream' }));
  }
  const dt = new DataTransfer();
  files.forEach(f => dt.items.add(f));
  const input = document.querySelector('input[type="file"]');
  if (input) {
    Object.defineProperty(input, 'files', { value: dt.files });
    input.dispatchEvent(new Event('change', { bubbles: true }));
    return `triggered upload of ${files.length} files (10MB each, ~50MB total)`;
  }
  return 'no file input found';
}

async () => {
  const results = [];
  for (let i = 1; i <= 10; i++) {
    const chunks = [];
    for (let j = 0; j < 160; j++) {
      const chunk = new Uint8Array(65536);
      crypto.getRandomValues(chunk);
      chunks.push(chunk);
    }
    const blob = new Blob(chunks, { type: 'application/octet-stream' });
    const file = new File([blob], `large-test-${i}.bin`, { type: 'application/octet-stream' });
    const dt = new DataTransfer();
    dt.items.add(file);
    const input = document.querySelector('input[type="file"]');
    if (input) {
      Object.defineProperty(input, 'files', { value: dt.files });
      input.dispatchEvent(new Event('change', { bubbles: true }));
      results.push(`${file.name}: ${(blob.size / 1024 / 1024).toFixed(1)}MB`);
      await new Promise(r => setTimeout(r, 500));
    }
  }
  return results.join(', ');
}

