 14→import { decrypt } from 'eciesjs';
 15→import { lookup } from 'node:dns/promises';
 16→import { getKeypair } from './tee-keys.js';
 17→
 18→export type ProviderConfig = {
 19→  endpoint: string;
 20→  authTokenBytes: Uint8Array; // SECURITY: Uint8Array for proper zeroing, NOT string
 21→  protocol: 'psa' | 'kubo';
 22→};
 23→
 24→export type MigrationBatchResult = {
 25→  succeeded: string[];
 26→  failed: string[];
 27→};
 28→
 29→// --- SSRF Protection (from security review CRITICAL finding) ---
 30→
 31→/**
 32→ * Validate endpoint URL to prevent SSRF attacks.
 33→ * TEE worker fetches from user-provided URLs -- must block internal/metadata endpoints.
 34→ */
 35→function validateEndpointUrl(endpoint: string): void {
 36→  const url = new URL(endpoint);
 37→
 38→  // Must be HTTPS
 39→  if (url.protocol !== 'https:') {
 40→    throw new Error('Migration endpoint must use HTTPS');
 41→  }
 42→
 43→  // Block private/internal IP ranges and metadata endpoints
 44→  const hostname = url.hostname;
 45→  if (
 46→    hostname === 'localhost' ||
 47→    hostname === '127.0.0.1' ||
 48→    hostname === '::1' ||
 49→    hostname.startsWith('10.') ||
 50→    hostname.startsWith('192.168.') ||
 51→    hostname === '169.254.169.254' ||
 52→    hostname.endsWith('.internal') ||
 53→    hostname.endsWith('.local') ||
 54→    hostname.startsWith('169.254.') ||
 55→    hostname.startsWith('fd') ||
 56→    hostname.startsWith('fe80')
 57→  ) {
 58→    throw new Error('Migration endpoint cannot target private/internal addresses');
 59→  }
 60→
 61→  // Block 172.16.0.0/12 range
 62→  if (hostname.startsWith('172.')) {
 63→    const second = parseInt(hostname.split('.')[1], 10);
 64→    if (second >= 16 && second <= 31) {
 65→      throw new Error('Migration endpoint cannot target private/internal addresses');
 66→    }
 67→  }
 68→}
 69→
 70→/**
 71→ * DNS rebinding protection: resolve hostname and verify IP is not private.
 72→ * Prevents attacker.com -> 169.254.169.254 attacks.
 73→ */
 74→async function validateResolvedIp(hostname: string): Promise<void> {
 75→  const result = await lookup(hostname);
 76→  const ip = result.address;
 77→  if (
 78→    ip.startsWith('10.') ||
 79→    ip.startsWith('192.168.') ||
 80→    ip.startsWith('127.') ||
 81→    ip === '::1' ||
 82→    ip.startsWith('169.254.') ||
 83→    ip.startsWith('fd') ||
 84→    ip.startsWith('fe80')
 85→  ) {
 86→    throw new Error('Migration endpoint DNS resolves to private address');
 87→  }
 88→  if (ip.startsWith('172.')) {
 89→    const second = parseInt(ip.split('.')[1], 10);
 90→    if (second >= 16 && second <= 31) {
 91→      throw new Error('Migration endpoint DNS resolves to private address');
 92→    }
 93→  }
 94→}
 95→
 96→// --- End SSRF Protection ---
 97→
 98→/**
 99→ * Decrypt an ECIES-encrypted provider config using TEE's current epoch key.
100→ * Returns raw bytes for parsing.
101→ */
102→async function decryptEcies(
103→  encryptedBase64: string,
104→  teePrivateKey: Uint8Array
105→): Promise<Uint8Array> {
106→  const ciphertext = new Uint8Array(Buffer.from(encryptedBase64, 'base64'));
107→  return new Uint8Array(decrypt(teePrivateKey, ciphertext));
108→}
109→
110→/**
111→ * Parse decrypted config bytes into ProviderConfig.
112→ * SECURITY: authToken stays as Uint8Array for proper zeroing.
113→ */
114→function parseProviderConfig(decryptedBytes: Uint8Array): ProviderConfig {
115→  const text = new TextDecoder().decode(decryptedBytes);
116→  const parsed = JSON.parse(text) as {
117→    endpoint: string;
118→    authToken: string;
119→    protocol: 'psa' | 'kubo';
120→  };
121→  return {
122→    endpoint: parsed.endpoint,
123→    authTokenBytes: new TextEncoder().encode(parsed.authToken),
124→    protocol: parsed.protocol,
125→  };
126→}
127→
128→/** Get auth token as string for HTTP header -- caller must zero authTokenBytes after use */
129→function authTokenString(config: ProviderConfig): string {
130→  return new TextDecoder().decode(config.authTokenBytes);
131→}
132→
133→/**
134→ * Migrate a batch of CIDs from source to destination provider.
135→ * Runs inside TEE -- credentials are decrypted in-enclave only.
136→ */
137→export async function migrateBatch(
138→  cids: string[],
139→  sourceConfigEncrypted: string,
140→  destConfigEncrypted: string,
141→  currentEpoch: number
142→): Promise<MigrationBatchResult> {
143→  // 1. Get TEE private key for this epoch
144→  const keypair = await getKeypair(currentEpoch);
145→  const teePrivateKey = keypair.privateKey;
146→
147→  // 2. Decrypt provider configs in-enclave (returns Uint8Array)
148→  const sourceConfigBytes = await decryptEcies(sourceConfigEncrypted, teePrivateKey);
149→  const destConfigBytes = await decryptEcies(destConfigEncrypted, teePrivateKey);
150→
151→  // Zero TEE private key immediately after decryption
152→  teePrivateKey.fill(0);
153→
154→  const sourceConfig = parseProviderConfig(sourceConfigBytes);
155→  const destConfig = parseProviderConfig(destConfigBytes);
156→
157→  // 2b. SSRF validation on both endpoints
158→  validateEndpointUrl(sourceConfig.endpoint);
159→  validateEndpointUrl(destConfig.endpoint);
160→  await validateResolvedIp(new URL(sourceConfig.endpoint).hostname);
161→  await validateResolvedIp(new URL(destConfig.endpoint).hostname);
162→
163→  const succeeded: string[] = [];
164→  const failed: string[] = [];
165→
166→  try {
167→    for (const cid of cids) {
168→      try {
169→        // 3. Fetch encrypted blob from source
170→        const data = await fetchFromProvider(cid, sourceConfig);
171→
172→        // 4. Pin to destination
173→        const destCid = await pinToProvider(data, cid, destConfig);
174→
175→        // 5. Verify CID match (content integrity)
176→        if (destCid !== cid) {
177→          throw new Error(`CID mismatch: expected ${cid}, got ${destCid}`);
178→        }
179→
180→        succeeded.push(cid);
181→      } catch {
182→        failed.push(cid);
183→      }
184→    }
185→  } finally {
186→    // 6. Zero credentials from memory (Uint8Array.fill(0) -- same pattern as republish.ts)
187→    sourceConfig.authTokenBytes.fill(0);
188→    destConfig.authTokenBytes.fill(0);
189→    sourceConfigBytes.fill(0);
190→    destConfigBytes.fill(0);
191→  }
192→
193→  return { succeeded, failed };
194→}
195→
196→async function fetchFromProvider(cid: string, config: ProviderConfig): Promise<Uint8Array> {
197→  if (config.protocol === 'kubo') {
198→    const token = authTokenString(config);
199→    const headers: Record<string, string> = token ? { Authorization: `Basic ${token}` } : {};
200→    const response = await fetch(`${config.endpoint}/api/v0/cat?arg=${encodeURIComponent(cid)}`, {
201→      method: 'POST',
202→      headers,
203→      signal: AbortSignal.timeout(60_000),
204→    });
205→    if (!response.ok) throw new Error(`Fetch from Kubo failed: ${response.status}`);
206→    return new Uint8Array(await response.arrayBuffer());
207→  }
208→
209→  // PSA: use IPFS gateway to fetch content (PSA has no retrieval API)
210→  const GATEWAY_URL = process.env.IPFS_GATEWAY_URL || 'https://ipfs.io';
211→  const response = await fetch(`${GATEWAY_URL}/ipfs/${encodeURIComponent(cid)}`, {
212→    signal: AbortSignal.timeout(60_000),
213→  });
214→  if (!response.ok) throw new Error(`Fetch from gateway failed: ${response.status}`);
215→  return new Uint8Array(await response.arrayBuffer());
216→}
217→
218→async function pinToProvider(
219→  data: Uint8Array,
220→  expectedCid: string,
221→  config: ProviderConfig
222→): Promise<string> {
223→  const token = authTokenString(config);
224→
225→  if (config.protocol === 'kubo') {
226→    // eslint-disable-next-line @typescript-eslint/no-explicit-any
227→    const blob = new Blob([data as any]);
228→    const formData = new FormData();
229→    formData.append('file', blob);
230→    const headers: Record<string, string> = {};
231→    if (token) headers['Authorization'] = `Basic ${token}`;
232→
233→    const response = await fetch(`${config.endpoint}/api/v0/add?pin=true&cid-version=1`, {
234→      method: 'POST',
235→      body: formData,
236→      headers,
237→      signal: AbortSignal.timeout(60_000),
238→    });
239→    if (!response.ok) throw new Error(`Pin to Kubo failed: ${response.status}`);
240→    const result = (await response.json()) as { Hash: string };
241→    return result.Hash;
242→  }
243→
244→  // PSA: pin by CID reference (data must already exist on IPFS network)
245→  const response = await fetch(`${config.endpoint}/pins`, {
246→    method: 'POST',
247→    headers: {
248→      Authorization: `Bearer ${token}`,
249→      'Content-Type': 'application/json',
250→    },
251→    body: JSON.stringify({
252→      cid: expectedCid,
253→      name: `migration-${Date.now()}`,
254→    }),
255→    signal: AbortSignal.timeout(30_000),
256→  });
257→  if (!response.ok) throw new Error(`PSA pin failed: ${response.status}`);
258→  const result = (await response.json()) as { pin: { cid: string } };
259→  return result.pin.cid;
260→}
261→
262→// NOTE: No zeroString function -- JS strings are immutable and cannot be zeroed.
263→// All credentials are processed as Uint8Array throughout and zeroed with .fill(0)
264→// in the finally block of migrateBatch(). This follows the existing pattern from
265→// tee-worker/src/routes/republish.ts:86 (ipnsPrivateKey.fill(0)).
266→

