 68→
 69→    // 401/403/422 means the endpoint exists and speaks Kubo, but auth failed
 70→    if (response.status === 401 || response.status === 403 || response.status === 422) {
 71→      return {
 72→        success: false,
 73→        protocol: 'kubo',
 74→        latencyMs,
 75→        error: 'authentication failed. check your auth token.',
 76→      };
 77→    }
 78→
 79→    // Other non-200 -- not Kubo, try PSA
 80→    return null;
 81→  } catch (err) {
 82→    const latencyMs = Math.round(performance.now() - start);
 83→
 84→    if (isCorsError(err)) {
 85→      return {
 86→        success: false,
 87→        latencyMs,
 88→        corsError: true,
 89→        corsInstructions: kuboCorsInstructions(endpoint),
 90→        error: 'CORS error: browser blocked the request. configure cors on your kubo node.',
 91→      };
 92→    }
 93→
 94→    if (isTimeoutError(err)) {
 95→      return {
 96→        success: false,
 97→        latencyMs,
 98→        error: 'connection timed out after 10 seconds.',
 99→      };
100→    }
101→
102→    // Other errors (e.g., DNS failure, network down) -- try PSA
103→    return null;
104→  }
105→}
