107→/** Probe PSA endpoint via GET /pins?limit=1 */
108→async function probePsa(
109→  endpoint: string,
110→  authToken?: string
111→): Promise<ConnectionTestResult | null> {
112→  const url = `${endpoint}/pins?limit=1`;
113→  const headers: Record<string, string> = {};
114→  if (authToken) {
115→    headers['Authorization'] = `Bearer ${authToken}`;
116→  }
117→
118→  const start = performance.now();
119→
120→  try {
121→    const response = await fetch(url, {
122→      method: 'GET',
123→      headers,
124→      signal: AbortSignal.timeout(PROBE_TIMEOUT_MS),
125→    });
126→
127→    const latencyMs = Math.round(performance.now() - start);
128→
129→    if (response.ok) {
130→      return {
131→        success: true,
132→        protocol: 'psa',
133→        latencyMs,
134→      };
135→    }
136→
137→    if (response.status === 401 || response.status === 403 || response.status === 422) {
138→      return {
139→        success: false,
140→        protocol: 'psa',
141→        latencyMs,
142→        error: 'authentication failed. check your auth token.',
143→      };
144→    }
145→
146→    // Other non-200 status -- not recognizable as PSA
147→    return null;
148→  } catch (err) {
149→    const latencyMs = Math.round(performance.now() - start);
150→
151→    if (isCorsError(err)) {
152→      return {
153→        success: false,
154→        latencyMs,
155→        corsError: true,
156→        corsInstructions: psaCorsInstructions(),
157→        error: 'CORS error: browser blocked the request. check your pinning service cors settings.',
158→      };
159→    }
160→
161→    if (isTimeoutError(err)) {
162→      return {
163→        success: false,
164→        latencyMs,
165→        error: 'connection timed out after 10 seconds.',
166→      };
167→    }
168→
169→    // Other errors
170→    return null;
171→  }
172→}
