174→/**
175→ * Detect CORS errors from fetch.
176→ * Browsers throw TypeError with specific messages when CORS blocks a request.
177→ */
178→function isCorsError(err: unknown): boolean {
179→  if (!(err instanceof TypeError)) return false;
180→  const message = err.message.toLowerCase();
181→  return (
182→    message.includes('failed to fetch') ||
183→    message.includes('networkerror') ||
184→    message.includes('network request failed')
185→  );
186→}
187→
188→/** Detect AbortSignal timeout errors */
189→function isTimeoutError(err: unknown): boolean {
190→  return err instanceof DOMException && err.name === 'AbortError';
191→}
