1014→  // ---- BYO-IPFS pinning ----
1015→
1016→  /**
1017→   * Pin encrypted data according to the configured pinning mode.
1018→   * Returns { cid, size } regardless of mode.
1019→   *
1020→   * Mode behavior:
1021→   * - cipherbox: standard addToIpfs (default, unchanged)
1022→   * - external+Kubo: KuboProvider.pin() directly, NO CipherBox relay.
1023→   *   If Kubo unreachable, throws (no silent fallback).
1024→   * - external+PSA: CipherBox relay for CID acquisition (PSA is CID-reference-only),
1025→   *   then PSA pinByCid, then unpin from CipherBox.
1026→   * - dual: CipherBox primary (must succeed), external secondary (best-effort).
1027→   */
1028→  private async pinWithMode(
1029→    encryptedData: Uint8Array,
1030→    ctx: SdkContext,
1031→    onProgress?: ProgressCallback
1032→  ): Promise<{ cid: string; size: number; secondaryWarning?: string }> {
1033→    const mode = this.config.pinningConfig?.mode ?? 'cipherbox';
1034→
1035→    if (mode === 'cipherbox' || !this.externalProvider) {
1036→      // Default: upload via CipherBox API relay
1037→      const result = await sdkCore.addToIpfs(ctx, encryptedData, onProgress);
1038→      return { cid: result.cid, size: result.size };
1039→    }
1040→
1041→    if (mode === 'external') {
1042→      const ext = this.config.pinningConfig!.externalProvider!;
1043→
1044→      if (ext.protocol === 'kubo') {
1045→        // Direct upload to user's Kubo node -- NO CipherBox involvement at all.
1046→        // If Kubo is unreachable, this throws. No silent fallback.
1047→        const result = await this.externalProvider.pin(encryptedData);
1048→        // Register CID with API for advisory tracking only
1049→        await sdkCore.registerCid(ctx, result.cid, result.size);
1050→        return { cid: result.cid, size: result.size };
1051→      }
1052→
1053→      // PSA: upload to CipherBox relay first (PSA can't accept raw data),
1054→      // then tell PSA to pin the CID, then unpin from CipherBox.
1055→      const relayResult = await sdkCore.addToIpfs(ctx, encryptedData, onProgress);
1056→      try {
1057→        await (this.externalProvider as sdkCore.PsaProvider).pinByCid(relayResult.cid);
1058→      } catch (err) {
1059→        // PSA pin failed, but data is still on CipherBox node
1060→        throw new Error(
1061→          `External PSA pin failed: ${err instanceof Error ? err.message : String(err)}. Data remains on CipherBox node.`
1062→        );
1063→      }
1064→      // PSA accepted the pin request -- unpin from CipherBox (async, best-effort)
1065→      sdkCore.unpinFromIpfs(ctx, relayResult.cid).catch(() => {});
1066→      // Register CID for advisory tracking
1067→      await sdkCore.registerCid(ctx, relayResult.cid, relayResult.size);
1068→      return { cid: relayResult.cid, size: relayResult.size };
1069→    }
1070→
1071→    // Dual mode: primary to CipherBox, secondary to external (best-effort)
1072→    const primaryResult = await sdkCore.addToIpfs(ctx, encryptedData, onProgress);
1073→    let secondaryWarning: string | undefined;
1074→    try {
1075→      const ext = this.config.pinningConfig!.externalProvider!;
1076→      if (ext.protocol === 'kubo') {
1077→        await this.externalProvider.pin(encryptedData);
1078→      } else {
1079→        await (this.externalProvider as sdkCore.PsaProvider).pinByCid(primaryResult.cid);
1080→      }
1081→    } catch {
1082→      secondaryWarning = `mirror to ${this.config.pinningConfig?.externalProvider?.providerName ?? 'external node'} failed -- will retry`;
1083→    }
1084→    return { cid: primaryResult.cid, size: primaryResult.size, secondaryWarning };
1085→  }
