1093→      userPrivateKey: this.config.vaultKeypair.privateKey,
1094→      userPublicKey: this.config.vaultKeypair.publicKey,
1095→      rootFolderKey: this.config.rootFolderKey,
1096→      teeKeys: this.config.teeKeys,
1097→    };
1098→  }
