 1→import type { PinningProvider, PinResult, PinStatus } from './types';
 2→
 3→export type DualPinResult = PinResult & {
 4→  secondarySuccess: boolean;
 5→  secondaryError?: string;
 6→};
 7→
 8→/**
 9→ * Orchestrates pinning to both a primary and secondary provider.
10→ *
11→ * Primary pin MUST succeed. Secondary pin is best-effort:
12→ * - If secondary fails, operation still succeeds with a warning.
13→ * - Caller receives secondarySuccess flag to show non-blocking toast.
14→ */
15→export class DualPinProvider implements PinningProvider {
16→  constructor(
17→    private readonly primary: PinningProvider,
18→    private readonly secondary: PinningProvider
19→  ) {}
20→
21→  async pin(data: Uint8Array, name?: string): Promise<DualPinResult> {
22→    // Primary MUST succeed
23→    const primaryResult = await this.primary.pin(data, name);
24→
25→    // Secondary is best-effort
26→    let secondarySuccess = false;
27→    let secondaryError: string | undefined;
28→    try {
29→      await this.secondary.pin(data, name);
30→      secondarySuccess = true;
31→    } catch (err) {
32→      secondaryError = err instanceof Error ? err.message : String(err);
33→    }
34→
35→    return {
36→      ...primaryResult,
37→      secondarySuccess,
38→      secondaryError,
39→    };
40→  }
41→
42→  async unpin(cid: string): Promise<void> {
43→    // Unpin from both, primary must succeed
44→    await this.primary.unpin(cid);
45→    // Secondary unpin is best-effort
46→    try {
47→      await this.secondary.unpin(cid);
48→    } catch {
49→      // Ignore secondary unpin failure
50→    }
51→  }
52→
53→  async status(cid: string): Promise<PinStatus> {
54→    // Status checks primary only
55→    return this.primary.status(cid);
56→  }
57→
58→  async get(cid: string): Promise<Uint8Array> {
59→    // Retrieve from primary
60→    return this.primary.get(cid);
61→  }
62→}
