 21→/**
 22→ * Hook for handling external file drops (from Finder/Explorer) anywhere in the app.
 23→ *
 24→ * Uses the SDK's uploadFile() for atomic encrypt → upload → register flow.
 25→ * All IPNS state is managed by the SDK — no dual-path conflicts.
 26→ */
 27→export function useDropUpload() {
 28→  const uploadStatus = useUploadStore((s) => s.status);
 29→  const isUploading =
 30→    uploadStatus === 'encrypting' || uploadStatus === 'uploading' || uploadStatus === 'registering';
 31→
 32→  const handleFileDrop = useCallback(async (files: File[], folderId: string): Promise<boolean> => {
 33→    // Filter out oversized files
 34→    const oversized = files.filter((f) => f.size > MAX_FILE_SIZE);
 35→    if (oversized.length > 0) {
 36→      useUploadStore
 37→        .getState()
 38→        .setError(`Files exceed 100MB limit: ${oversized.map((f) => f.name).join(', ')}`);
 39→      return false;
 40→    }
 41→
 42→    if (files.length === 0) return false;
 43→
 44→    // Check quota
 45→    const totalSize = files.reduce((sum, f) => sum + f.size, 0);
 46→    const quotaStore = useQuotaStore.getState();
 47→    if (!quotaStore.canUpload(totalSize)) {
 48→      useUploadStore.getState().setError('Not enough storage space for these files');
 49→      return false;
 50→    }
 51→
 52→    // Check for duplicates within batch
 53→    const batchNames = new Set<string>();
 54→    for (const f of files) {
 55→      if (batchNames.has(f.name)) {
 56→        useUploadStore.getState().setError(`Duplicate file name in selection: ${f.name}`);
 57→        return false;
 58→      }
 59→      batchNames.add(f.name);
 60→    }
 61→
 62→    // Identify which files already exist in the target folder
 63→    const folder = useFolderStore.getState().folders[folderId];
 64→    const existingByName = new Map<string, string>(); // name → fileId
 65→    const existingFolderNames = new Set<string>();
 66→    if (folder) {
 67→      for (const child of folder.children) {
 68→        if (child.type === 'file') {
 69→          existingByName.set(child.name, child.id);
 70→        } else if (child.type === 'folder') {
 71→          existingFolderNames.add(child.name);
 72→        }
 73→      }
 74→    }
 75→
 76→    // Fail fast on file–folder name collisions
 77→    const folderNameConflicts = files.filter((f) => existingFolderNames.has(f.name));
 78→    if (folderNameConflicts.length > 0) {
 79→      useUploadStore
 80→        .getState()
 81→        .setError(
 82→          `Cannot upload file(s) with the same name as an existing folder: ${folderNameConflicts.map((f) => f.name).join(', ')}`
 83→        );
 84→      return false;
 85→    }
 86→
 87→    const newFiles = files.filter((f) => !existingByName.has(f.name));
 88→    const duplicateFiles = files.filter((f) => existingByName.has(f.name));
 89→
 90→    if (!hasSdkClient()) {
 91→      useUploadStore.getState().setError('SDK not initialized — please log in again');
 92→      return false;
 93→    }
 94→
 95→    const client = getSdkClient();
 96→
 97→    // Resolve parent folder and ensure it's registered in the SDK
 98→    const folders = useFolderStore.getState().folders;
 99→    const vault = useVaultStore.getState();
100→    const parentFolder =
101→      folderId === 'root' ? getRootFolderState(vault, folders) : folders[folderId];
102→    if (!parentFolder) {
103→      useUploadStore.getState().setError('Parent folder not found');
104→      return false;
105→    }
106→    ensureFolderRegistered(parentFolder);
107→
108→    const uploadStore = useUploadStore.getState();
109→    // Start with all files (new + duplicates) since we encrypt all upfront
110→    uploadStore.startUpload(files.length);
111→
112→    const uploadedCids: string[] = []; // Track for cleanup on failure
113→
114→    try {
115→      // Upload new files via SDK (atomic: encrypt → IPFS → FilePointer → IPNS publish)
116→      for (const file of newFiles) {
117→        if (useUploadStore.getState().status === 'cancelled') {
118→          throw new Error('Upload cancelled by user');
119→        }
120→
121→        useUploadStore.getState().setUploading(file.name, 0);
122→
123→        // Read File to Uint8Array
124→        const data = new Uint8Array(await file.arrayBuffer());
125→
126→        const result = await client.uploadFile(
127→          parentFolder.ipnsName,
128→          data,
129→          file.name,
130→          file.type || 'application/octet-stream',
131→          (percent) => useUploadStore.getState().setUploading(file.name, percent)
132→        );
133→
134→        uploadedCids.push(result.cid);
135→        useUploadStore.getState().fileComplete();
136→      }
137→
138→      // Handle duplicate files: encrypt + upload to IPFS, then surface as pending replacements
139→      // (These don't get registered in the folder — the user decides via the Replace dialog)
140→      if (duplicateFiles.length > 0) {
141→        const replacements: PendingReplacement[] = [];
142→
143→        // Hoist dynamic imports before the loop to avoid per-iteration async overhead
144→        const { encryptFile } = await import('../services/file-crypto.service');
145→        const { addToIpfs } = await import('../lib/api/ipfs');
146→
147→        for (const file of duplicateFiles) {
148→          if (useUploadStore.getState().status === 'cancelled') {
149→            throw new Error('Upload cancelled by user');
150→          }
151→
152→          useUploadStore.getState().setUploading(file.name, 0);
153→
154→          // For duplicates, we only encrypt + upload to IPFS (don't register in folder)
155→          // Use the old upload service for this since SDK's uploadFile registers in folder
156→          const userPublicKey = useAuthStore.getState().vaultKeypair?.publicKey;
157→          if (!userPublicKey) throw new Error('No keypair available');
158→          const encrypted = await encryptFile(file, userPublicKey);
159→          // Pass a clean Uint8Array copy — never use .buffer (may include extra bytes)
160→          const blob = new Blob([new Uint8Array(encrypted.ciphertext)], {
161→            type: 'application/octet-stream',
162→          });
163→          const ipfsResult = await addToIpfs(blob, (percent) =>
164→            useUploadStore.getState().setUploading(file.name, percent)
165→          );
166→
167→          uploadedCids.push(ipfsResult.cid);
168→          useUploadStore.getState().fileComplete();
169→
170→          const existingFileId = existingByName.get(file.name);
171→          if (existingFileId) {
172→            replacements.push({
173→              fileName: file.name,
174→              fileId: existingFileId,
175→              parentId: folderId,
176→              encryptedData: {
177→                cid: ipfsResult.cid,
178→                wrappedKey: encrypted.wrappedKey,
179→                iv: encrypted.iv,
180→                size: file.size,
181→                encryptionMode: encrypted.encryptionMode,
182→              },
183→            });
184→          }
185→        }
186→
187→        if (replacements.length > 0) {
188→          useUploadStore.getState().setPendingReplacements(replacements);
189→        }
190→      }
191→
192→      useUploadStore.getState().setSuccess();
193→      return true;
194→    } catch (err) {
195→      const message = (err as Error).message;
196→      if (message !== 'Upload cancelled by user') {
197→        useUploadStore.getState().setError(message);
198→      }
199→      // Best-effort cleanup: unpin orphaned CIDs from failed upload
200→      if (uploadedCids.length > 0) {
201→        import('../lib/api/ipfs')
202→          .then(({ unpinFromIpfs }) => {
203→            for (const cid of uploadedCids) {
204→              unpinFromIpfs(cid).catch(() => {});
205→            }
206→          })
207→          .catch(() => {});
208→      }
209→      return false;
210→    } finally {
211→      // Refresh quota from server
212→      await useQuotaStore.getState().fetchQuota();
213→    }
214→  }, []);
215→
216→  return { handleFileDrop, isUploading };
217→}
