16→/**
17→ * Initialize the SDK client. Called after vault is loaded (login complete).
18→ * The client persists for the session and is destroyed on logout.
19→ *
20→ * If a client already exists (e.g., session restoration), it is destroyed
21→ * before creating the new one.
22→ */
23→export function initSdkClient(config: CipherBoxClientConfig): CipherBoxClient {
24→  if (_client) {
25→    _client.destroy();
26→  }
27→  // Inject the shared axios instance so CipherBoxClient uses the same
28→  // instance as orval-generated functions (single instance, no dual path).
29→  _client = new CipherBoxClient({ ...config, axiosInstance: apiAxios });
30→  return _client;
31→}
