33→/**
34→ * Get the current SDK client instance.
35→ * Throws if called before initSdkClient() (i.e., before login).
36→ */
37→export function getSdkClient(): CipherBoxClient {
38→  if (!_client) {
39→    throw new Error('SDK client not initialized. Call initSdkClient() after login.');
40→  }
41→  return _client;
42→}
43→
44→/**
45→ * Check if the SDK client is initialized (for conditional usage).
46→ */
47→export function hasSdkClient(): boolean {
48→  return _client !== null;
49→}
