51→/**
52→ * Destroy the SDK client. Called on logout.
53→ * Clears internal state, key caches, and event subscriptions.
54→ */
55→export function destroySdkClient(): void {
56→  if (_client) {
57→    _client.destroy();
58→    _client = null;
59→  }
