62→/**
63→ * Ensure a folder from the Zustand store is registered in the SDK's
64→ * internal FolderTree. This bridges the gap between folder navigation
65→ * (which loads folders into Zustand) and SDK operations (which require
66→ * folders in the SDK's internal state).
67→ *
68→ * Only registers if the SDK doesn't already have the folder. The SDK's
69→ * internal state (sequence number, children, keys) is authoritative once
70→ * a folder is registered — all mutations go through the SDK.
71→ */
72→export function ensureFolderRegistered(folder: FolderNode): void {
73→  const client = getSdkClient();
74→
75→  // Don't overwrite if SDK already has this folder — its internal state
76→  // is authoritative (correct sequence number, keys, children from mutations)
77→  if (client.hasFolder(folder.ipnsName)) return;
78→
79→  // Guard: don't register placeholder folders with empty key material —
80→  // would cause crypto/IPNS errors on subsequent mutations
81→  if (folder.folderKey.length === 0 || folder.ipnsPrivateKey.length === 0) {
82→    return;
83→  }
84→
85→  client.registerFolder(
86→    folder.ipnsName,
87→    folder.folderKey,
88→    {
89→      publicKey: new Uint8Array(0), // Public key derived from private key when needed
90→      privateKey: folder.ipnsPrivateKey,
91→    },
92→    folder.children,
93→    folder.sequenceNumber
94→  );
95→}
