 52→  const plaintext = await unwrapKey(encrypted, userPrivateKey);
 53→  try {
 54→    const json = new TextDecoder().decode(plaintext);
 55→    return JSON.parse(json) as ByoIpfsConfig;
 56→  } finally {
 57→    clearBytes(plaintext);
 58→  }
