    /** Probe Pinata API via GET /data/testAuthentication */
    async function probePinata(
      endpoint: string,
      authToken?: string
    ): Promise<ConnectionTestResult | null> {
      // Pinata detection: try the test authentication endpoint
      const url = `${endpoint}/data/testAuthentication`;
      const headers: Record<string, string> = {};
      if (authToken) {
        headers['Authorization'] = `Bearer ${authToken}`;
      }

      const start = performance.now();

      try {
        const response = await fetch(url, {
          method: 'GET',
          headers,
          signal: AbortSignal.timeout(PROBE_TIMEOUT_MS),
        });

        const latencyMs = Math.round(performance.now() - start);

        if (response.ok) {
          return {
            success: true,
            protocol: 'pinata',
            version: 'Pinata API v3',
            latencyMs,
          };
        }

        if (response.status === 401 || response.status === 403) {
          return {
            success: false,
            protocol: 'pinata',
            latencyMs,
            error: 'authentication failed. check your pinata jwt token.',
          };
        }

        return null;
      } catch (err) {
        const latencyMs = Math.round(performance.now() - start);

        if (isCorsError(err)) {
          // Pinata API should support CORS, but if not:
          return {
            success: false,
            latencyMs,
            corsError: true,
            corsInstructions: 'pinata api should support browser requests. check if your jwt token has the correct permissions.',
            error: 'CORS error when connecting to pinata.',
          };
        }

        return null;
      }
    }
